    static int ថ្នាក់_ឈ្មោះ_អត្ថបទ(int 수) { return ត្រួតពិនិត្យ_តំលៃថេរ(수, 7) && ត្រួតពិនិត្យ_តំលៃថេរ(상가[수], 1) ? 상가[수] : 0; }
